slides.code:
background-color:颜色预设值 | 十六进制值 | RGB 值 | transparent | inherit;
background-color:#ccc;

background-image:url(image_file_path) | inherit;
background-image:url(images/01.jpg);

background:bg-color bg-image position/bg-size bg-repeat bg-origin bg-clip bg-attachment initial|inherit;

background:red url("images/bg.png") repeat-y;
background:#fff center/80% no-repeat;
background:url("images/bg.png") left top/cover no-repeat content-box;

.icon-dot{                  /* #007-#017 */
    display: inline-block;
    width: 100px;
    height: 100px;
    padding:10px;
    border:10px solid;
    background-color: currentColor;
    background-clip:content-box;
    color:lightgrey;
    border-radius: 50%;
}
.icon-menu{                 /* #018-#028 */
    display: inline-block;
    width: 140px;
    height: 10px;
    padding:35px 0;
    border-top:10px solid;
    border-bottom:10px solid;
    color:lightgrey;
    background-color: currentColor;
    background-clip: content-box;
}

.box{                       /* #007-#014 */
    width: 172px;
    height: 200px;
    border:1px solid #ccc;
    float: left;
    margin-right: 10px;
    background: url("image/bdd.png") no-repeat;
}
.bdd1{background-position: 0 0;}            /* #015 */
.bdd2{background-position: -172px 0;}       /* #016 */
.bdd3{background-position: -344px 0;}       /* #017 */
.bdd4{background-position: 0px -200px;}     /* #018 */
.bdd5{background-position: -172px -200px;}  /* #019 */
.bdd6{background-position: -344px -200px;}  /* #020 */
.bdd7{background-position: -516px -98px;}   /* #021 */
